def wordBreakList(s: str, wordDict: list[str]) -> list[str]:
    words = set(wordDict)
    memo = {}
    def dfs(sub):
        if sub in memo: return memo[sub]
        if not sub: return [""]
        res = []
        for w in words:
            if sub.startswith(w):
                sub_res = dfs(sub[len(w):])
                for rest in sub_res:
                    res.append(w + (" " + rest if rest else ""))
        memo[sub] = res
        return res
    return sorted(dfs(s))

